  const [isSwiped, setIsSwiped] = useState(false);

  const handleSwipeLeft = () => {
    setIsSwiped(true);
    onDelete(item);
  };

  const handleSwipeRight = () => {
    setIsSwiped(false);
    onUndo(item);
  };

  return (
    <motion.div
      className='flex items-center justify-between p-4 bg-sage rounded-lg'
      drag='x'
      dragConstraints={{ left: -100, right: 0 }}
      onDragEnd={(e, { offset }) => {
        if (offset.x < -50) {
          handleSwipeLeft();
        } else if (offset.x > 50) {
          handleSwipeRight();
        }
      }}
    >
      {isSwiped ? (
        <motion.div
          className='bg-terracotta rounded-lg p-2'
          initial={{ opacity: 0, x: -10 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: 10 }}
        >
          Delete
        </motion.div>
      ) : (
        <div>{item}</div>
      )}
    </motion.div>
  );
