    align-items: center;
    justify-content: center;
    font-size: 24px;
    cursor: pointer;
    transition: background-color 0.3s;
  }
  .card.flipped {
    background-color: #fff;
  }
  .move-counter, .timer {
    margin-top: 20px;
    font-size: 18px;
  }
</style>
