<div class="game-board" id="gameBoard"></div>
<div class="move-counter">Moves: <span id="moveCounter">0</span></div>
<div class="timer">Time: <span id="timer">00:00</span></div>

<script>
  const cardValues = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];
  const gameBoard = document.getElementById('gameBoard');
  const moveCounterElement = document.getElementById('moveCounter');
  const timerElement = document.getElementById('timer');

  let cards = [];
  let moves = 0;
  let time = 0;
  let interval;

  function shuffleArray(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
  }

  function createBoard() {
    shuffleArray(cardValues);
    for (let i = 0; i < cardValues.length; i++) {
      const card = document.createElement('div');
      card.classList.add('card');
      card.dataset.value = cardValues[i];
      card.addEventListener('click', flipCard);
      gameBoard.appendChild(card);
      cards.push(card);
    }
  }

  function flipCard(event) {
    const card = event.target;
    if (card.classList.contains('flipped')) return;

    card.classList.add('flipped');
    moves++;
    moveCounterElement.textContent = moves;

    if (cards.filter(c => c.classList.contains('flipped')).length === 2) {
      const flippedCards = cards.filter(c => c.classList.contains('flipped'));
      setTimeout(() => {
        if (flippedCards[0].dataset.value !== flippedCards[1].dataset.value) {
          flippedCards.forEach(c => c.classList.remove('flipped'));
        }
      }, 1000);
    }

    if (moves === cardValues.length * 2) {
      clearInterval(interval);
      alert('Congratulations! You found all pairs!');
    }
  }

  function startTimer() {
    interval = setInterval(() => {
      time++;
      const minutes = Math.floor(time / 60);
      const seconds = time % 60;
      timerElement.textContent = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
    }, 1000);
  }

  createBoard();
  startTimer();
</script>
