        class Toast {
            constructor(message, options = {}) {
                this.message = message;
                this.options = {
                    duration: 5000,
                    autoDismiss: true,
                    ...options
                };
                this.element = document.createElement('div');
                this.element.classList.add('toast');
                this.element.innerHTML = `
                    <span>${this.message}</span>
                    <span class="close-btn">X</span>
                `;
                document.getElementById('toast-container').appendChild(this.element);
                if (this.options.autoDismiss) {
                    setTimeout(() => this.dismiss(), this.options.duration);
                }
                this.element.querySelector('.close-btn').addEventListener('click', () => this.dismiss());
            }

            dismiss() {
                this.element.remove();
            }
        }

        function showToast(message, options = {}) {
            new Toast(message, options);
        }

        // Example usage:
